/*
 * A276786  a(1) = 1; subsequent terms are defined by the rule that if m is
 *          present so are 2m+1 and 3m+1; repeated terms are included; final
 *          list is sorted.
 * https://oeis.org/A276786
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   The sequence is generated by a priority‑queue method. Start with
 *            1. When a number m is extracted, insert 2m+1 and 3m+1 into a
 *            min‑heap. Output the numbers in increasing order, keeping
 *            duplicates, and return the nth (1‑based) output
 * Range:     u8 n <= 31, u16 n <= 4328, u32 n <= 8922, u64 n <= 8922,
 *            u128 n <= 8922, big any n
 * Helpers:   heap_swap
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/heap_swap.h"

/* ----- heap helpers ----------------------------------------------------- */
static seq_t *heap_arr = NULL;
static size_t heap_sz = 0, heap_cap = 0;

static void heap_sift_up(size_t i) {
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap_arr[p] <= heap_arr[i]) break;
        heap_swap(&heap_arr[p], &heap_arr[i]);
        i = p;
    }
}

static void heap_sift_down(size_t i) {
    while (1) {
        size_t l = (i << 1) + 1;
        if (l >= heap_sz) break;
        size_t r = l + 1;
        size_t smallest = l;
        if (r < heap_sz && heap_arr[r] < heap_arr[l]) smallest = r;
        if (heap_arr[smallest] >= heap_arr[i]) break;
        heap_swap(&heap_arr[smallest], &heap_arr[i]);
        i = smallest;
    }
}

static void heap_push(seq_t v) {
    if (heap_sz == heap_cap) {
        heap_cap = heap_cap ? heap_cap << 1 : 16;
        heap_arr = (seq_t*)realloc(heap_arr, heap_cap * sizeof(seq_t));
    }
    heap_arr[heap_sz++] = v;
    heap_sift_up(heap_sz - 1);
}

static seq_t heap_pop(void) {
    seq_t v = heap_arr[0];
    --heap_sz;
    if (heap_sz) {
        heap_arr[0] = heap_arr[heap_sz];
        heap_sift_down(0);
    }
    return v;
}

/* ----- cache helpers ---------------------------------------------------- */
static seq_t *cache = NULL;
static size_t cache_sz = 0, cache_cap = 0;

static void cache_grow(size_t needed) {
    if (cache_cap < needed) {
        size_t new_cap = cache_cap ? cache_cap << 1 : 16;
        while (new_cap < needed) new_cap <<= 1;
        cache = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }
}

/* ----- public function ---------------------------------------------------- */
seq_t a(idx_t n) {
    if (n == (idx_t)0) return (seq_t)0;   /* n < 1: undefined, but harmless */
    if (cache_sz < (size_t)n) {
        cache_grow((size_t)n);
        /* initialise heap once */
        if (heap_cap == 0) heap_push((seq_t)1);
        while (cache_sz < (size_t)n) {
            seq_t m = heap_pop();
            cache[cache_sz++] = m;
            heap_push(m * (seq_t)2 + (seq_t)1);
            heap_push(m * (seq_t)3 + (seq_t)1);
        }
    }
    return cache[(size_t)n - 1];
}
